#!/usr/bin/env python3
"""Заключение пояснительной записки в оформлении образца (заголовок «ЗАКЛЮЧЕНИЕ» по центру без номера).
Использование: python3 build_z.py [выход.docx]
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.shared import Cm
from build_2 import Doc, KURS


def build(out):
    b = Doc(chap=0)
    h = b._p('Heading 1')
    h.alignment = WD_ALIGN_PARAGRAPH.CENTER
    h.paragraph_format.first_line_indent = Cm(0)
    h.paragraph_format.left_indent = Cm(0)
    h.add_run('ЗАКЛЮЧЕНИЕ')
    b.empty()
    b.text('В ходе выполнения курсового проекта разработано программное средство дистанционного банковского обслуживания физических лиц «ТалерБанк». Цель проекта достигнута, задачи, поставленные во введении, решены.')
    b.text('Проанализирована предметная область, построены функциональная модель процесса кредитования в нотации IDEF0, информационная модель и UML-модели, сформулированы функциональные требования. Спроектировано и реализовано веб-приложение на Node.js и Express по шаблону MVC с базой данных MySQL и интерфейсом на HTML5, CSS3 и JavaScript. Все денежные операции учитываются по принципу двойной записи в транзакциях с блокировкой строк, разработаны алгоритмы переводов, начисления процентов по вкладам, построения графиков платежей и оценки кредитоспособности логистической регрессией.')
    b.text('Программное средство поддерживает шесть категорий пользователей и более пятнадцати бизнес-операций, от открытия счетов и переводов до выдачи кредитов, контроля подозрительных операций и закрытия операционного дня. Данные защищены хэшированием паролей, двухфакторной аутентификацией, защитой от подделки запросов, шифрованием паспортных данных и резервных копий. Программные тесты и тесты бизнес-логики завершились успешно, а дефекты, найденные при тестировании, исправлены. Подготовлены руководство по установке программного средства и руководство пользователя для каждой роли.')
    b.text('Программное средство соответствует требованиям задания. Бизнес-логика написана на JavaScript с описанием типов в комментариях JSDoc и разделена на модули ECMAScript, база данных обеспечивает ссылочную целостность, интерфейс использует единственную каскадную таблицу стилей и работает в браузерах Яндекс Браузер, Firefox, Chrome и Opera в среде Windows 10 и новее. Хранимые и передаваемые данные шифруются, а резервные копии базы данных создаются автоматически по расписанию.')
    b.text('Практическая значимость работы состоит в том, что клиент выполняет основные банковские операции без посещения отделения, типовая кредитная заявка рассматривается автоматически сразу после подачи, а сотрудники банка занимаются только операциями, требующими их решения. Учёт по принципу двойной записи и неизменяемый журнал аудита позволяют в любой момент проверить правильность остатков и восстановить историю действий пользователей.')
    b.text('В дальнейшем программное средство можно развивать в нескольких направлениях. Это разработка мобильного приложения, работающего с тем же программным интерфейсом, подключение межбанковской системы идентификации для удалённой регистрации клиентов, доставка кодов подтверждения по SMS и push-уведомлениями, поддержка межбанковских переводов в иностранной валюте, а также дообучение модели оценки кредитоспособности на истории погашения выданных кредитов.')
    b.save(out)


if __name__ == '__main__':
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.join(KURS, 'zaklyuchenie.docx')
    build(out)
    print(out)
